import {beginBottomDialogue} from './bottom-dialogue.js';
import {ULTIMATE_CINEMATIC_STEPS} from '../engine/ultimate-rules.js';
import {BOA_META} from './boa-meta.js';
import {boaPose} from '../characters/boa_hancock.js';
import {personalCaster} from '../engine/personal-ultimate.js';
export function boaSprite(ctx,images,key,row,col,x,y,scale=1,angle=0,face=1){const im=images[key],m=BOA_META[key];if(!im?.complete||!im.naturalWidth||!m)return;const [w,h]=m.frameSize,[px,py]=m.pivot;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*(face<0?-1:1),scale);ctx.drawImage(im,Math.max(0,Math.min(m.columns-1,col))*w,Math.max(0,Math.min(m.rows-1,row))*h,w,h,-px,-py,w,h);ctx.restore();}
export function drawBoaActor(ctx,images,d,f,hurt=false,override=null){const c=personalCaster(d,f),a=d.personalUltimate?.attack;let pose=override||boaPose(f,hurt);if(c?.kind==='judgment')pose={row:11,frame:Math.min(5,Math.floor((d.personalUltimate.cinematic?.elapsed??ULTIMATE_CINEMATIC_STEPS+d.tick-c.born)/12))};if(a?.kind==='judgment'&&a.ownerUid===f.uid&&a.phase==='travel'&&d.tick-a.launch<66){const age=d.tick-a.launch;pose=age<30?{row:11,frame:5}:{row:12,frame:Math.min(5,Math.floor((age-30)/6))};}if(f.state==='defeat')pose={row:6,frame:Math.min(5,Math.floor((d.tick-(f.deathTick??d.tick))/6))};boaSprite(ctx,images,f.introAge!=null?'boa_hancock_intro':'boa_hancock',pose.row,pose.frame,f.x,f.y,.86,0,f.face);}
export function drawBoaBack(ctx,images,d){for(const f of d.fighters)if(f.id==='boa_hancock'&&f.hp>0&&f.introAge!=null){const age=f.introAge;ctx.save();ctx.globalAlpha=Math.min(1,age*5,(2.5-age)*5);boaSprite(ctx,images,'boa_hancock_intro_vfx',0,Math.min(5,Math.floor(age/2.5*6)),f.x,f.y,.75);if(age>.35&&age<2.2)boaSprite(ctx,images,'boa_hancock_intro_vfx',1,Math.min(5,Math.floor((age-.35)/1.85*6)),f.x,f.y-70,.75);ctx.restore();}}
export function drawBoaWorld(ctx,images,d,reduced=false){for(const f of d.fighters){if(f.hp>0&&d.tick<(f.petrifyUntil||0)){ctx.save();ctx.globalAlpha=.6;boaSprite(ctx,images,'boa_hancock_vfx',3,d.tick>=f.petrifyUntil-12?5:4,f.x,f.y-55,.75);ctx.restore();}if(f.id==='boa_hancock'&&f.hp>0&&f.introAge!=null&&f.introAge>1.2&&f.introAge<1.95){ctx.save();ctx.globalAlpha=.5;boaSprite(ctx,images,'boa_hancock_intro_vfx',2,Math.min(5,Math.floor((f.introAge-1.2)/.75*6)),f.x,f.y-70,.7);ctx.restore();}}
 const a=d.personalUltimate?.attack;if(a?.kind==='judgment'&&a.phase==='warning'){ctx.save();ctx.strokeStyle='#ffb3d9';ctx.lineWidth=2;ctx.setLineDash([14,9]);for(const side of [-1,1]){ctx.beginPath();ctx.moveTo(a.x-a.dy*100*side,a.y+a.dx*100*side);ctx.lineTo(a.x+a.dx*1200-a.dy*100*side,a.y+a.dy*1200+a.dx*100*side);ctx.stroke();}ctx.restore();boaSprite(ctx,images,'boa_hancock_ultimate_vfx',0,Math.min(5,Math.floor((d.tick-a.born)/6)),a.x+a.dx*55,a.y+a.dy*55-60,.85);}}
export function drawBoaShot(ctx,images,s,x,y,clock){const ultimate=s.skill==='judgment'||s.kind.startsWith('judgment'),kick=s.kind==='judgmentkick',row=ultimate?(kick?2:1):s.kind==='heartarrow'?1:0;boaSprite(ctx,images,ultimate?'boa_hancock_ultimate_vfx':'boa_hancock_vfx',row,kick?3:ultimate?3+Math.floor(clock*12)%2:s.kind==='heartarrow'?3+Math.floor(clock*12)%2:2+Math.floor(clock*12)%2,x,y,ultimate?1:.65,Math.atan2(s.vy,s.vx));}
export function drawBoaChat(ctx,images,c,line='Know your place before your empress.',reduced=false){const p=c.elapsed/ULTIMATE_CINEMATIC_STEPS;beginBottomDialogue(ctx,'boa');ctx.globalAlpha=Math.max(0,Math.min(1,p*10,(1-p)*12));const slide=reduced?0:Math.max(0,1-p*9)*65;boaSprite(ctx,images,'boa_hancock_dialogue',0,p>.45?1:0,480+slide,310,.8);boaSprite(ctx,images,'boa_hancock_dialogue',2,p>.5?1:0,225+slide,315,.23);ctx.textAlign='center';ctx.fillStyle='#fff0d2';ctx.font='bold 17px Georgia';ctx.fillText('BOA HANCOCK',408+slide,249,170);ctx.font='bold 24px Georgia';ctx.fillText(line,565+slide,333,445);ctx.restore();}
export function drawBoaCinematic(ctx,images,d,reduced=false){const c=d.personalUltimate?.cinematic,a=d.personalUltimate?.attack;if((c||a)?.kind!=='judgment')return;if(c)drawBoaChat(ctx,images,c,undefined,reduced);else if(a.phase==='travel'&&d.tick-a.launch<48){ctx.save();ctx.globalAlpha=Math.min(1,(48-d.tick+a.launch)/12);boaSprite(ctx,images,'boa_hancock_dialogue',3,0,480,92,.6);ctx.restore();}}
